-- User-defined tables and objects, as in SAP: OUTB lists the "@<Name>" tables
-- (ObjectType 0 no object, 1 master data, 2 master data rows, 3 document,
-- 4 document rows, 5 no object with auto-increment code); OUDO registers a UDO
-- (TYPE 1 master data, 3 document) and UDO1 its child tables. The "@<Name>"
-- tables themselves are created at runtime by UserTablesMD.

CREATE TABLE IF NOT EXISTS "OUTB" (
  "TableName" VARCHAR(20) PRIMARY KEY,
  "Descr" VARCHAR(100),
  "TblNum" INTEGER GENERATED BY DEFAULT AS IDENTITY,
  "ObjectType" SMALLINT NOT NULL DEFAULT 0 CHECK ("ObjectType" BETWEEN 0 AND 5)
);

CREATE TABLE IF NOT EXISTS "OUDO" (
  "Code" VARCHAR(20) PRIMARY KEY,
  "Name" VARCHAR(100) NOT NULL,
  "TableName" VARCHAR(20) NOT NULL REFERENCES "OUTB" ("TableName"),
  "TYPE" SMALLINT NOT NULL CHECK ("TYPE" IN (1, 3)),
  "MngSeries" CHAR(1) NOT NULL DEFAULT 'N',
  "CanDelete" CHAR(1) NOT NULL DEFAULT 'N',
  "CanClose" CHAR(1) NOT NULL DEFAULT 'N',
  "CanCancel" CHAR(1) NOT NULL DEFAULT 'N',
  "CanFind" CHAR(1) NOT NULL DEFAULT 'N',
  "CanLog" CHAR(1) NOT NULL DEFAULT 'N',
  "CanDefForm" CHAR(1) NOT NULL DEFAULT 'N'
);

CREATE TABLE IF NOT EXISTS "UDO1" (
  "Code" VARCHAR(20) NOT NULL REFERENCES "OUDO" ("Code") ON DELETE CASCADE,
  "SonNum" INTEGER NOT NULL,
  "TableName" VARCHAR(20) NOT NULL REFERENCES "OUTB" ("TableName"),
  "SonName" VARCHAR(50) NOT NULL,
  PRIMARY KEY ("Code", "SonNum")
);
